```bash
# File: reset-local.sh — undo a LOCAL (unshared) commit. Rewrites history.

git log --oneline -2
#   bad1234 (HEAD) wrong interest rate 9% committed by mistake
#   good567 baseline

# SOFT: move pointer back; KEEP changes staged (redo the commit cleanly).
git reset --soft HEAD~1
git status            # changes from bad1234 are STAGED, ready to recommit

# MIXED (default): move pointer back; UNSTAGE but keep changes in working dir.
git reset HEAD~1      # equivalent to --mixed

# HARD: move pointer back AND discard staged + working changes (DANGEROUS).
git reset --hard HEAD~1   # bad1234 changes GONE from working tree
# Safe here ONLY because bad1234 was never pushed.
```

```bash
# File: revert-shared.sh — undo an ALREADY-PUSHED commit. Preserves history.

git log --oneline -2 origin/main
#   push999 (origin/main) BUG: posted interest twice
#   base888 baseline

# Create a NEW commit that is the inverse of push999. Nothing rewritten.
git revert push999
# Git opens an editor for the revert message; save it. A new commit appears:
git log --oneline -2
#   rev000a Revert "BUG: posted interest twice"
#   push999 BUG: posted interest twice     <-- original STILL in history
git push origin main    # teammates just pull ONE extra commit; nothing breaks
```

```bash
# File: reflog-recover.sh — recover a "lost" commit after a bad hard reset.

# Oops: hard reset removed a GOOD commit from the branch.
git reset --hard HEAD~1    # good commit now unreferenced (looks lost)

# reflog remembers every place HEAD pointed, including BEFORE the reset.
git reflog
#   a1b2c3d HEAD@{0}: reset: moving to HEAD~1
#   d4e5f6g HEAD@{1}: commit: good interest fix   <-- the one we want back
#   ...

# Restore by resetting back to that reflog entry (or branch it).
git reset --hard HEAD@{1}
# good interest fix is back on the branch.
git log --oneline -1
```

