package com.bank.interest;

import java.math.BigDecimal;
import java.math.RoundingMode;

// The service whose commits we reset, revert, and recover.
public class InterestPostingService {

    // Post monthly interest at the CORRECT annual rate (fixed via revert).
    public BigDecimal monthlyInterest(BigDecimal balance, BigDecimal annualRatePercent) {
        BigDecimal monthlyRate = annualRatePercent
                .divide(new BigDecimal("100"))
                .divide(new BigDecimal("12"), 10, RoundingMode.HALF_UP);
        return balance.multiply(monthlyRate).setScale(2, RoundingMode.HALF_UP);
    }
}
